type Mod = { providers: string[]; exports: string[]; imports: Mod[] };

const prisma: Mod = { providers: ['PrismaService'], exports: ['PrismaService'], imports: [] };
const tarefas: Mod = {
  providers: ['TarefasService', 'CalculoPrazo'],
  exports: ['TarefasService'],
  imports: [prisma],
};
const plano: Mod = { providers: ['PlanoService'], exports: [], imports: [tarefas] };

function enxerga(m: Mod, token: string): boolean {
  return m.providers.includes(token) || m.imports.some((i) => i.exports.includes(token));
}

