type Handler = () => Promise<unknown>;
type Interceptor = (proximo: Handler) => Promise<unknown>;

const log: Interceptor = async (proximo) => {
  console.log('log: antes');
  const resposta = await proximo();
  console.log('log: depois');
  return resposta;
};
const envelope: Interceptor = async (proximo) => ({ data: await proximo() });

const handler: Handler = async () => {
  console.log('handler');
  return [1, 2];
};

const cadeia = [log, envelope].reduceRight<Handler>(
  (proximo, interceptor) => () => interceptor(proximo),
  handler,
);
console.log(JSON.stringify(await cadeia()));

const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function comLimite(handler: () => Promise<string>, ms: number) {
  const limite = espera(ms).then(() => {
    throw new Error('408 Request Timeout');
  });
  try {
    return await Promise.race([handler(), limite]);
  } catch (e) {
    return (e as Error).message;
  }
}

