console.log(statusDe(new HttpErro('x')));

function requisicao(autenticado: boolean, corpoValido: boolean): string {
  const passos: string[] = [];
  try {
    passos.push('middleware');
    passos.push('guard');
    if (!autenticado) throw new Error('401');
