type Req = { headers: Record<string, string>; cookies?: Record<string, string> };
type Middleware = (req: Req, next: () => void) => void;

function cookieParser(): Middleware {
  return (req, next) => {
    const texto = req.headers['cookie'] ?? '';
    const pares = texto.split('; ').filter(Boolean).map((p) => p.split('='));
    req.cookies = Object.fromEntries(pares);
    next();
  };
}

